From b43e27fa31f62e91a0f32960cae1deda7f9f0297 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 16:14:14 +0100
Subject: [PATCH] PackageJob: Don't delete the target of a symlinked package on
 uninstall

Uninstalling a widget that is a symlink deleted the folder the link points
to, because the package path has symlinks resolved. Now the unresolved path
is passed on and only the link is removed, also when updating over a link.

BUG: 508717
---
 src/kpackage/packagejob.cpp               | 2 +-
 src/kpackage/private/packagejobthread.cpp | 5 ++++-
 2 files changed, 5 insertions(+), 2 deletions(-)

diff --git a/src/kpackage/packagejob.cpp b/src/kpackage/packagejob.cpp
index 06a22ce..650d0a7 100644
--- a/src/kpackage/packagejob.cpp
+++ b/src/kpackage/packagejob.cpp
@@ -146,7 +146,7 @@ PackageJob *PackageJob::uninstall(const QString &packageFormat, const QString &p
         package.setPath(uninstallPath);

         PackageLoader::invalidateCache();
-        auto job = new PackageJob(Uninstall, package, QString(), QString());
+        auto job = new PackageJob(Uninstall, package, uninstallPath, QString());
         job->start();
         return job;
     } else {
diff --git a/src/kpackage/private/packagejobthread.cpp b/src/kpackage/private/packagejobthread.cpp
index e137684..a7ff203 100644
--- a/src/kpackage/private/packagejobthread.cpp
+++ b/src/kpackage/private/packagejobthread.cpp
@@ -70,6 +70,9 @@ bool copyFolder(QString sourcePath, QString targetPath)

 bool removeFolder(QString folderPath)
 {
+    if (QFileInfo(folderPath).isSymLink()) {
+        return QFile::remove(folderPath);
+    }
     QDir folder(folderPath);
     return folder.removeRecursively();
 }
@@ -98,7 +101,7 @@ PackageJobThread::PackageJobThread(PackageJob::OperationType type, const QString
             update(src, dest, package);
         };
     } else if (type == PackageJob::Uninstall) {
-        const QString packagePath = package.path();
+        const QString packagePath = QFileInfo(src).isSymLink() ? src : package.path();
         d->run = [this, packagePath]() {
             uninstall(packagePath);
         };
